import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class DOMNodePointer_getLanguage_TriageGen2Test {

    @Mock
    private Node mockNode;

    @Mock
    private Element mockElement;

    @Mock
    private Node mockParent;

    @Test
    public void testGetLanguage_ReturnsAttributeWhenPresent() {
        // Setup: node is an Element with xml:lang="en"
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockNode.getParentNode()).thenReturn(null);
        // We need to cast mockNode to Element for the logic to work via the mock setup
        // In a real scenario, we'd use a real DOM implementation or a more complex mock
        // Since the method casts (Element) n, we must ensure the mock behaves like an Element
        Node elementNode = org.mockito.Mockito.mock(Element.class, org.mockito.Mockito.withSettings().extraInterfaces(Element.class));
        when(elementNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(elementNode.getAttribute("xml:lang")).thenReturn("en");
        when(elementNode.getParentNode()).thenReturn(null);

        DOMNodePointer pointer = new DOMNodePointer(elementNode, Locale.ENGLISH);

        String result = invokeGetLanguage(pointer);
        assertEquals("en", result);
    }

    @Test
    public void testGetLanguage_ReturnsParentAttributeWhenChildHasNoLang() {
        // Setup: Child is TEXT_NODE, Parent is ELEMENT_NODE with xml:lang="fr"
        Node textNode = org.mockito.Mockito.mock(Node.class);
        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(mockParent);

        Element parentElement = org.mockito.Mockito.mock(Element.class, org.mockito.Mockito.withSettings().extraInterfaces(Element.class));
        when(mockParent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockParent.getParentNode()).thenReturn(null);
        when(parentElement.getAttribute("xml:lang")).thenReturn("fr");

        // Re-mocking parent to be the element
        when(textNode.getParentNode()).thenReturn(parentElement);

        DOMNodePointer pointer = new DOMNodePointer(textNode, Locale.FRENCH);

        String result = invokeGetLanguage(pointer);
        assertEquals("fr", result);
    }

    @Test
    public void testGetLanguage_ReturnsNullWhenAttributeIsEmpty() {
        // Setup: Element has xml:lang=""
        Element element = org.mockito.Mockito.mock(Element.class, org.mockito.Mockito.withSettings().extraInterfaces(Element.class));
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("xml:lang")).thenReturn("");
        when(element.getParentNode()).thenReturn(null);

        DOMNodePointer pointer = new DOMNodePointer(element, Locale.ENGLISH);

        String result = invokeGetLanguage(pointer);
        assertNull(result);
    }

    @Test
    public void testGetLanguage_ReturnsNullWhenAttributeIsNull() {
        // Setup: Element has xml:lang=null
        Element element = org.mockito.Mockito.mock(Element.class, org.mockito.Mockito.withSettings().extraInterfaces(Element.class));
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("xml:lang")).thenReturn(null);
        when(element.getParentNode()).thenReturn(null);

        DOMNodePointer pointer = new DOMNodePointer(element, Locale.ENGLISH);

        String result = invokeGetLanguage(pointer);
        assertNull(result);
    }

    @Test
    public void testGetLanguage_ReturnsNullWhenNoNodesInHierarchyHaveLang() {
        // Setup: Hierarchy of nodes, none are elements with the attribute
        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(mockNode.getParentNode()).thenReturn(mockParent);
        when(mockParent.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(mockParent.getParentNode()).thenReturn(null);

        DOMNodePointer pointer = new DOMNodePointer(mockNode, Locale.ENGLISH);

        String result = invokeGetLanguage(pointer);
        assertNull(result);
    }

    @Test
    public void testGetLanguage_ReturnsNullWhenNodeIsNull() {
        // Setup: Initial node is null
        DOMNodePointer pointer = new DOMNodePointer(null, Locale.ENGLISH);

        String result = invokeGetLanguage(pointer);
        assertNull(result);
    }

    /**
     * Helper to access the protected method via reflection since it's a unit test 
     * for a protected method in a different package/class scope.
     */
    private String invokeGetLanguage(DOMNodePointer pointer) {
        try {
            java.lang.reflect.Method method = DOMNodePointer.class.getDeclaredMethod("getLanguage");
            method.setAccessible(true);
            return (String) method.invoke(pointer);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
